@inject sv_2698b8cedec04fe594e5672cec23a92f.Services.WarehouseState WarehouseState
@inject sv_2698b8cedec04fe594e5672cec23a92f.Services.InventoryAlertService AlertService
@inject sv_2698b8cedec04fe594e5672cec23a92f.Services.InventoryAlertState AlertState

<PageTitle>Dashboard — @WarehouseState.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">@WarehouseState.SelectedWarehouseName</h5>
        <p class="card-text">
