            <span class="badge bg-danger fs-6">@AlertState.LowStockCount</span>
        </p>
        <p class="text-muted small mb-0">
            Polling every 10 seconds. Last checked: @_lastChecked?.ToString("HH:mm:ss")
        </p>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private DateTime? _lastChecked;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(OnWarehouseChanged);
        WarehouseState.OnChange += _warehouseHandler;

        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertState.OnChange += _alertHandler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await PollOnceAsync();
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken token)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(token))
            {
                await PollOnceAsync();
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task PollOnceAsync()
    {
        var count = await AlertService.GetLowStockCountAsync(WarehouseState.SelectedWarehouseId);
        _lastChecked = DateTime.Now;
        // Updating via the shared state notifies ALL subscribers (sidebar badge, etc.)
        AlertState.UpdateCount(count);
    }

    private async Task OnWarehouseChanged()
    {
        // Warehouse changed — poll immediately for the new warehouse
        await PollOnceAsync();
        StateHasChanged();
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= _warehouseHandler;
        AlertState.OnChange -= _alertHandler;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

